const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const Joi = require('joi');
const app = express();

// ==========================================
// SECURITY MIDDLEWARE
// ==========================================

// Security headers using Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
  },
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Stricter rate limit for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20, // 20 requests per 15 minutes
  message: {
    error: 'Rate limit exceeded for this endpoint.',
  },
});

// Request body size limit (prevent DoS via large payloads)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// CORS configuration (adjust origins as needed)
app.use((req, res, next) => {
  const allowedOrigins = process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'];
  const origin = req.headers.origin;

  if (allowedOrigins.includes(origin)) {
    res.setHeader('Access-Control-Allow-Origin', origin);
  }

  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  res.setHeader('Access-Control-Allow-Credentials', 'true');
  res.setHeader('Access-Control-Max-Age', '86400'); // 24 hours

  if (req.method === 'OPTIONS') {
    return res.sendStatus(204);
  }

  next();
});

// Request ID for tracking
app.use((req, res, next) => {
  req.id = req.headers['x-request-id'] || Math.random().toString(36).substring(2, 15);
  res.setHeader('X-Request-ID', req.id);
  next();
});

// ==========================================
// INPUT VALIDATION SCHEMAS
// ==========================================

const userQuerySchema = Joi.object({
  id: Joi.number().integer().positive().optional(),
  email: Joi.string().email().max(254).optional(),
  limit: Joi.number().integer().min(1).max(100).default(10),
  offset: Joi.number().integer().min(0).default(0),
});

const updateUserSchema = Joi.object({
  name: Joi.string().min(1).max(100).required(),
  email: Joi.string().email().max(254).required(),
});

// ==========================================
// VALIDATION MIDDLEWARE
// ==========================================

const validate = (schema) => {
  return (req, res, next) => {
    const { error, value } = schema.validate(req.query, {
      abortEarly: false,
      stripUnknown: true,
    });

    if (error) {
      const errors = error.details.map(detail => ({
        field: detail.path.join('.'),
        message: detail.message,
      }));

      return res.status(400).json({
        error: 'Validation failed',
        details: errors,
        requestId: req.id,
      });
    }

    req.query = value;
    next();
  };
};

const validateBody = (schema) => {
  return (req, res, next) => {
    const { error, value } = schema.validate(req.body, {
      abortEarly: false,
      stripUnknown: true,
    });

    if (error) {
      const errors = error.details.map(detail => ({
        field: detail.path.join('.'),
        message: detail.message,
      }));

      return res.status(400).json({
        error: 'Validation failed',
        details: errors,
        requestId: req.id,
      });
    }

    req.body = value;
    next();
  };
};

// ==========================================
// ROUTES
// ==========================================

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    requestId: req.id,
  });
});

// Get users with validation
app.get('/users', validate(userQuerySchema), (req, res) => {
  try {
    const { limit, offset } = req.query;

    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    ];

    // Apply filters based on query parameters
    let filteredUsers = allUsers;

    if (req.query.email) {
      filteredUsers = filteredUsers.filter(u => u.email === req.query.email);
    }

    if (req.query.id) {
      filteredUsers = filteredUsers.filter(u => u.id === req.query.id);
    }

    // Apply pagination with bounds checking
    const startIndex = Math.min(offset, filteredUsers.length);
    const endIndex = Math.min(startIndex + limit, filteredUsers.length);
    const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

    res.json({
      data: paginatedUsers,
      meta: {
        total: filteredUsers.length,
        limit,
        offset,
        hasMore: endIndex < filteredUsers.length,
      },
      requestId: req.id,
    });
  } catch (error) {
    // Will be caught by error handler middleware
    next(error);
  }
});

// Get single user by ID
app.get('/users/:id strictLimiter, (req, res, next) => {
  try {
    const userId = parseInt(req.params.id, 10);

    if (isNaN(userId) || userId <= 0) {
      return res.status(400).json({
        error: 'Invalid user ID',
        requestId: req.id,
      });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({
        error: 'User not found',
        requestId: req.id,
      });
    }

    res.json({
      data: user,
      requestId: req.id,
    });
  } catch (error) {
    next(error);
  }
});

// Create new user
app.post('/users', strictLimiter, validateBody(updateUserSchema), (req, res, next) => {
  try {
    const { name, email } = req.body;

    // Additional validation logic
    if (name === 'admin') {
      return res.status(403).json({
        error: 'Reserved username',
        requestId: req.id,
      });
    }

    const newUser = {
      id: Date.now(),
      name,
      email,
    };

    res.status(201).json({
      data: newUser,
      requestId: req.id,
    });
  } catch (error) {
    next(error);
  }
});

// ==========================================
// ERROR HANDLING
// ==========================================

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Endpoint not found',
    path: req.path,
    method: req.method,
    requestId: req.id,
  });
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error for debugging (in production, use structured logging)
  console.error(`[${req.id}] Error:`, {
    name: err.name,
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip,
  });

  // Handle specific error types
  if (err instanceof SyntaxError && err.status === 400 && 'body' in err) {
    return res.status(400).json({
      error: 'Invalid JSON in request body',
      requestId: req.id,
    });
  }

  if (err.type === 'entity.parse.failed') {
    return res.status(400).json({
      error: 'Failed to parse request data',
      requestId: req.id,
    });
  }

  // Default error response
  const statusCode = err.statusCode || err.status || 500;
  const message = process.env.NODE_ENV === 'development' 
    ? err.message 
    : 'Internal server error';

  res.status(statusCode).json({
    error: message,
    requestId: req.id,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
  });
});

// ==========================================
// GRACEFUL SHUTDOWN
// ==========================================

const server = app.listen(3000, () => {
  console.log('Server running on port 3000');
});

const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force close after 10 seconds
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;

