const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Security headers with Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  noSniff: true,
  frameguard: { action: 'deny' },
  xssFilter: true
}));

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Stricter rate limiting for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 10, // Limit each IP to 10 requests per windowMs
  message: {
    error: 'Rate limit exceeded for this endpoint.'
  }
});

// Apply rate limiting to all routes
app.use(limiter);

// Body parser with size limits
app.use(express.json({ 
  limit: '10kb', // Limit request body size
  strict: true 
}));

app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb' 
}));

// ============================================================================
// INPUT VALIDATION MIDDLEWARE
// ============================================================================

/**
 * Middleware to handle validation errors
 */
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path || err.param,
        message: err.msg,
        value: err.value
      }))
    });
  }
  next();
};

/**
 * Sanitization helper function
 */
const sanitizeString = (str) => {
  if (typeof str !== 'string') return str;
  return str.trim().replace(/[<>]/g, '');
};

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

/**
 * 404 Not Found Handler
 */
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource was not found',
    path: req.path
  });
});

/**
 * Global Error Handler
 */
app.use((err, req, res, next) => {
  // Log error (in production, use proper logging service)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    url: req.url,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Don't leak error details in production
  const statusCode = err.statusCode || 500;
  const response = {
    error: err.name || 'Internal Server Error',
    message: process.env.NODE_ENV === 'development' 
      ? err.message 
      : 'An unexpected error occurred'
  };

  // Add request ID if available
  if (req.id) {
    response.requestId = req.id;
  }

  res.status(statusCode).json(response);
});

/**
 * Async handler wrapper to catch errors in async route handlers
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint
 * No authentication required
 */
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

/**
 * Get users endpoint with query parameter validation
 */
app.get('/users', 
  [
    // Validate and sanitize query parameters
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be an integer between 1 and 100')
      .toInt(),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer')
      .toInt(),
    query('sort')
      .optional()
      .isIn(['id', 'name', 'email'])
      .withMessage('Sort must be one of: id, name, email'),
    query('order')
      .optional()
      .isIn(['asc', 'desc'])
      .withMessage('Order must be either asc or desc')
  ],
  handleValidationErrors,
  asyncHandler(async (req, res) => {
    const { limit = 10, offset = 0, sort = 'id', order = 'asc' } = req.query;

    // Simulated database query with validation
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    ];

    // Apply sorting
    users.sort((a, b) => {
      const aVal = a[sort];
      const bVal = b[sort];
      const comparison = aVal < bVal ? -1 : aVal > bVal ? 1 : 0;
      return order === 'desc' ? -comparison : comparison;
    });

    // Apply pagination
    const paginatedUsers = users.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      meta: {
        total: users.length,
        limit,
        offset,
        hasMore: offset + limit < users.length
      }
    });
  })
);

/**
 * Get user by ID endpoint with path parameter validation
 */
app.get('/users/:id',
  [
    param('id')
      .isInt({ min: 1 })
      .withMessage('User ID must be a positive integer')
      .toInt()
  ],
  handleValidationErrors,
  asyncHandler(async (req, res) => {
    const { id } = req.params;

    // Simulated database query
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    ];

    const user = users.find(u => u.id === id);

    if (!user) {
      return res.status(404).json({
        error: 'User Not Found',
        message: `No user found with ID: ${id}`
      });
    }

    res.json({ data: user });
  })
);

/**
 * Create user endpoint with body validation
 */
app.post('/users',
  strictLimiter, // Stricter rate limiting for writes
  [
    body('name')
      .trim()
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters')
      .matches(/^[a-zA-Z\s'-]+$/)
      .withMessage('Name contains invalid characters'),
    body('email')
      .trim()
      .isEmail()
      .withMessage('Must be a valid email address')
      .normalizeEmail()
      .isLength({ max: 255 })
      .withMessage('Email address too long')
  ],
  handleValidationErrors,
  asyncHandler(async (req, res) => {
    const { name, email } = req.body;

    // Additional sanitization
    const sanitizedName = sanitizeString(name);

    // Simulate user creation
    const newUser = {
      id: Date.now(), // In production, use proper ID generation
      name: sanitizedName,
      email: email.toLowerCase()
    };

    res.status(201).json({
      message: 'User created successfully',
      data: newUser
    });
  })
);

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// ============================================================================
// GRACEFUL SHUTDOWN
// ============================================================================

const shutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  server.close(() => {
    console.log('Server closed successfully');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forcing shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  shutdown('uncaughtException');
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  shutdown('unhandledRejection');
});

module.exports = app;

