// Secure Express application with proper error handling and input validation
const express = require('express');
const helmet = require('helmet');
const { body, query, param, validationResult } = require('express-validator');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');

const app = express();

// ===== Security Middleware =====

// HTTP security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
  },
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Request logging
app.use(morgan('combined'));

// Body parsing with size limits
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ===== Validation Helper Functions =====

/**
 * Validates request data and returns 400 if validation fails
 * @param {Object} req - Express request object
 * @param {Object} res - Express response object
 * @param {Function} next - Express next middleware function
 * @returns {void}
 */
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array(),
    });
  }
  next();
};

/**
 * Async handler to catch errors in async route handlers
 * @param {Function} fn - Async route handler function
 * @returns {Function} Express middleware function
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ===== Error Handling Middleware =====

/**
 * Global error handler
 */
app.use((err, req, res, next) => {
  // Log error for debugging (in production, use proper logging service)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    url: req.url,
    method: req.method,
    ip: req.ip,
  });

  // Don't leak error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: {
      message: isDevelopment ? err.message : 'Internal server error',
      ...(isDevelopment && { stack: err.stack }),
    },
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Route ${req.method} ${req.path} not found`,
  });
});

// ===== Mock Data with Sanitization =====

/**
 * Get all users with basic sanitization
 * @returns {Array} Sanitized user data
 */
const getUsers = () => {
  return [
    { 
      id: 1, 
      name: 'Alice', 
      email: 'alice@example.com',
      // In real app, never expose internal IDs or sensitive data
    },
    { 
      id: 2, 
      name: 'Bob', 
      email: 'bob@example.com',
    },
  ].map(user => ({
    // Sanitize output to prevent XSS
    id: user.id,
    name: escapeHtml(user.name),
    email: escapeHtml(user.email),
  }));
};

/**
 * Escape HTML to prevent XSS attacks
 * @param {string} text - Text to escape
 * @returns {string} Escaped text
 */
const escapeHtml = (text) => {
  if (typeof text !== 'string') return text;
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
};

// ===== Routes =====

/**
 * Health check endpoint
 */
app.get('/health', asyncHandler(async (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
  });
}));

/**
 * Get users endpoint with validation
 */
app.get('/users', 
  [
    // Validate query parameters if any were used
    query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
    query('offset').optional().isInt({ min: 0 }).toInt(),
  ],
  validateRequest,
  asyncHandler(async (req, res) => {
    const { limit = 10, offset = 0 } = req.query;

    try {
      const users = getUsers();
      const paginatedUsers = users.slice(offset, offset + limit);

      res.json({
        data: paginatedUsers,
        meta: {
          total: users.length,
          limit,
          offset,
        },
      });
    } catch (error) {
      throw new Error('Failed to retrieve users');
    }
  })
);

/**
 * Get user by ID endpoint validation example
 */
app.get('/users/:id',
  [
    // Validate ID parameter
    param('id')
      .isInt({ min: 1 })
      .withMessage('ID must be a positive integer')
      .toInt()
  ],
  validateRequest,
  asyncHandler(async (req, res) => {
    const { id } = req.params;

    const users = getUsers();
    const user = users.find(u => u.id === id);

    if (!user) {
      const error = new Error('User not found');
      error.status = 404;
      throw error;
    }

    res.json({ data: user });
  })
);

/**
 * Example POST endpoint with body validation
 */
app.post('/users',
  [
    // Validate request body
    body('name')
      .trim()
      .notEmpty()
      .withMessage('Name is required')
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters')
      .matches(/^[a-zA-Z0-9\s\-']+$/)
      .withMessage('Name contains invalid characters'),

    body('email')
      .trim()
      .notEmpty()
      .withMessage('Email is required')
      .isEmail()
      .withMessage('Invalid email format')
      .normalizeEmail()
      .isLength({ max: 255 })
      .withMessage('Email is too long'),
  ],
  validateRequest,
  asyncHandler(async (req, res) => {
    const { name, email } = req.body;

    // In real app, save to database with proper transaction
    // This is just an example
    const newUser = {
      id: Date.now(), // Not production-ready ID generation
      name: escapeHtml(name),
      email: escapeHtml(email),
    };

    res.status(201).json({ data: newUser });
  })
);

// ===== Server Configuration =====

const PORT = process.env.PORT || 3000;

// Handle server startup errors
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle uncaught rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, you might want to close the server gracefully
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // In production, perform cleanup and exit
  process.exit(1);
});

// Graceful shutdown
const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);
  server.close(() => {
    console.log('Server closed successfully');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

module.exports = app;

