## Sanitization Function Reference

```javascript
/**
 * Escape HTML to prevent XSS attacks
 */
const escapeHtml = (text) => {
  if (typeof text !== 'string') return text;
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
};

/**
 * Deep escape all string properties in an object
 */
const deepEscapeHtml = (obj) => {
  if (typeof obj === 'string') {
    return escapeHtml(obj);
  } else if (Array.isArray(obj)) {
    return obj.map(deepEscapeHtml);
  } else if (obj && typeof obj === 'object') {
    const escaped = {};
    for (const key in obj) {
      escaped[key] = deepEscapeHtml(obj[key]);
    }
    return escaped;
  }
  return obj;
};
```

