## 🚨 Common Security Pitfalls to Avoid

```javascript
// ❌ BAD: Direct string concatenation
const query = `SELECT * FROM users WHERE id = ${req.params.id}`;

// ✅ GOOD: Parameterized queries
const query = 'SELECT * FROM users WHERE id = ?', [req.params.id];

// ❌ BAD: No validation
app.get('/file/:name', (req, res) => {
  res.sendFile(req.params.name);  // Path traversal vulnerability!
});

// ✅ GOOD: Validate and sanitize
app.get('/file/:name', 
  [param('name').matches(/^[\w\-\.]+$/)],
  validate,
  (req, res) => {
    const sanitized = path.basename(req.params.name);
    res.sendFile(sanitized);
  }
);

// ❌ BAD: Exposing stack traces
app.use((err, req, res, next) => {
  res.json({ error: err.stack });  // Don't do this!
});

// ✅ GOOD: Safe error messages
app.use((err, req, res, next) => {
  res.status(500).json({ 
    error: process.env.NODE_ENV === 'development' 
      ? err.message 
      : 'Internal server error' 
  });
});

// ❌ BAD: Trusting client input
const user = JSON.parse(req.body.user);

// ✅ GOOD: Validate and parse safely
const user = JSON.parse(req.body.user);
const schema = Joi.object({ name: Joi.string() });
const { error } = schema.validate(user);
if (error) return res.status(400).json({ error: error.message });
```

