      .withMessage('Sort must be one of: id, name, email')
      .customSanitizer(value => sanitizeInput(value)),
    query('fields')
      .optional()
      .customSanitizer(value => {
        if (typeof value === 'string') {
          return value.split(',').map(f => sanitizeInput(f.trim()));
        }
        return value;
      }),
  ],
  validateRequest,
  asyncHandler(async (req, res) => {
    const { limit = 10, offset = 0, sort = 'id', fields } = req.query;

    // Mock data (in production, this would come from a database)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    ];

    // Apply sorting
    const sortedUsers = [...allUsers].sort((a, b) => {
      if (a[sort] < b[sort]) return -1;
      if (a[sort] > b[sort]) return 1;
      return 0;
    });

    // Apply pagination
    const paginatedUsers = sortedUsers.slice(offset, offset + limit);

    // Filter fields if specified
    let responseBody = { users: paginatedUsers };
    if (fields && Array.isArray(fields)) {
      const validFields = ['id', 'name', 'email'];
      const requestedFields = fields.filter(f => validFields.includes(f));
      responseBody.users = paginatedUsers.map(user => {
        const filteredUser = {};
        requestedFields.forEach(field => {
          if (user[field] !== undefined) {
