/**
 * Example POST endpoint with comprehensive validation
 */
app.post('/users',
  apiLimiter,
  [
    // Validate request body
    body('name')
      .trim()
      .notEmpty()
      .withMessage('Name is required')
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters')
      .matches(/^[a-zA-Z\s'-]+$/)
      .withMessage('Name contains invalid characters')
      .customSanitizer(value => sanitizeInput(value)),
    body('email')
      .trim()
      .notEmpty()
      .withMessage('Email is required')
      .isEmail()
      .withMessage('Invalid email format')
      .normalizeEmail()
      .isLength({ max: 255 })
      .withMessage('Email must not exceed 255 characters'),
  ],
  validateRequest,
  asyncHandler(async (req, res) => {
    const { name, email } = req.body;

    // In production, save to database
    const newUser = {
      id: Date.now(), // In production, use proper ID generation
      name,
      email,
      createdAt: new Date().toISOString(),
    };

    logSecurityEvent('info', 'User created', { userId: newUser.id, email });

