// Secure Express application with proper error handling and input validation

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all routes
app.use(limiter);

// Stricter rate limiting for user endpoints
const userLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 30,
  message: {
    error: 'Too many user requests, please try again later.',
  },
});

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============================================================================
// INPUT VALIDATION & SANITIZATION HELPERS
// ============================================================================

/**
 * Middleware to handle validation errors
 */
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
      })),
    });
  }
  next();
};

/**
 * Sanitize user data before sending response
 */
const sanitizeUserData = (user) => ({
  id: user.id,
  name: user.name.replace(/[<>]/g, ''), // Remove potentially dangerous characters
  email: user.email,
  // Remove any sensitive fields that shouldn't be exposed
});

/**
 * Generate unique request ID for tracing
 */
const requestIdMiddleware = (req, res, next) => {
  req.id = req.headers['x-request-id'] || Math.random().toString(36).substring(7);
  res.setHeader('X-Request-ID', req.id);
  next();
};

app.use(requestIdMiddleware);

/**
 * Security logging middleware
 */
const securityLogger = (req, res, next) => {
  const start = Date.now();

  // Log request details (excluding sensitive data)
  console.log(`[${new Date().toISOString()}] ${req.id} ${req.method} ${req.path} - IP: ${req.ip}`);

  // Log response
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`[${new Date().toISOString()}] ${req.id} ${req.method} ${req.path} - Status: ${res.statusCode} - ${duration}ms`);
  });

  next();
};

app.use(securityLogger);

// ============================================================================
// ERROR HANDLING
// ============================================================================

/**
 * Global error handler
 */
app.use((err, req, res, next) => {
  // Log the error with request ID for tracing
  console.error(`[${new Date().toISOString()}] ${req.id} ERROR:`, {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip,
  });

  // Don't leak internal errors in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal server error',
    requestId: req.id,
    ...(isDevelopment && { stack: err.stack }),
  });
});

/**
 * 404 handler
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    requestId: req.id,
  });
});

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint with detailed status
 */
app.get('/health', 
  [
    query('detailed').optional().isBoolean().withMessage('detailed must be a boolean'),
  ],
  handleValidationErrors,
  (req, res) => {
    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      request_id: req.id,
    };

    // Only include detailed info if explicitly requested (and in development)
    if (req.query.detailed === 'true' && process.env.NODE_ENV === 'development') {
      healthData.memory = process.memoryUsage();
      healthData.version = process.version;
    }

    res.json(healthData);
  }
);

/**
 * Get users endpoint with pagination and validation
 */
app.get('/users',
  userLimiter,
  [
    query('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
    query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
    query('search').optional().trim().escape().isLength({ max: 100 }).withMessage('Search term too long'),
  ],
  handleValidationErrors,
  (req, res) => {
    try {
      const page = parseInt(req.query.page) || 1;
      const limit = parseInt(req.query.limit) || 10;
      const search = req.query.search;

      // Mock user data - in production, this would come from a database
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
        { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      ];

      // Filter by search term if provided
      let filteredUsers = allUsers;
      if (search) {
        const searchTerm = search.toLowerCase();
        filteredUsers = allUsers.filter(user => 
          user.name.toLowerCase().includes(searchTerm) || 
          user.email.toLowerCase().includes(searchTerm)
        );
      }

      // Pagination
      const startIndex = (page - 1) * limit;
      const endIndex = startIndex + limit;
      const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

      // Sanitize output
      const sanitizedUsers = paginatedUsers.map(sanitizeUserData);

      res.json({
        data: sanitizedUsers,
        pagination: {
          page,
          limit,
          total: filteredUsers.length,
          totalPages: Math.ceil(filteredUsers.length / limit),
        },
        request_id: req.id,
      });
    } catch (error) {
      throw error; // Let the global error handler handle it
    }
  }
);

/**
 * Get user by ID with parameter validation
 */
app.get('/users/:id',
  userLimiter,
  [
    param('id').isInt({ min: 1 }).withMessage('User ID must be a positive integer'),
  ],
  handleValidationErrors,
  (req, res) => {
    try {
      const userId = parseInt(req.params.id);

      // Mock user lookup - in production, this would be a database query
      const users = {
        1: { id: 1, name: 'Alice', email: 'alice@example.com' },
        2: { id: 2, name: 'Bob', email: 'bob@example.com' },
        3: { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      };

      const user = users[userId];

      if (!user) {
        return res.status(404).json({
          error: 'User not found',
          request_id: req.id,
        });
      }

      res.json({
        data: sanitizeUserData(user),
        request_id: req.id,
      });
    } catch (error) {
      throw error;
    }
  }
);

// ============================================================================
// SERVER STARTUP
// ============================================================================

if (require.main === module) {
  const PORT = process.env.PORT || 3000;

  const server = app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
    console.log(`Security: Helmet enabled, Rate limiting active`);
  });

  // Graceful shutdown
  process.on('SIGTERM', () => {
    console.log('SIGTERM received, shutting down gracefully...');
    server.close(() => {
      console.log('Server closed');
      process.exit(0);
    });
  });

  process.on('SIGINT', () => {
    console.log('SIGINT received, shutting down gracefully...');
    server.close(() => {
      console.log('Server closed');
      process.exit(0);
    });
  });
}

module.exports = app;

