# App.js Security Review and Recommendations

## Current State Analysis

The current `app.js` is a minimal Express.js application with the following endpoints:
- `/health` - Returns server status
- `/users` - Returns a static list of users

## Security Vulnerabilities Identified

### 1. **No Input Validation**
- No validation on query parameters, headers, or request bodies
- No sanitization of any incoming data

### 2. **No Rate Limiting**
- Vulnerable to DoS attacks
- No protection against brute force attempts

### 3. **No Error Handling**
- No global error handler
- Unhandled promises could crash the server
- Error messages might leak sensitive information

### 4. **Missing Security Headers**
- No Helmet.js for security headers
- Missing CORS configuration
- No CSP (Content Security Policy)

### 5. **No Request Size Limits**
- Vulnerable to payload size attacks
- No protection against large request bodies

### 6. **No Logging**
- No request logging for security monitoring
- No audit trail

### 7. **Missing Environment Configuration**
- Hardcoded port number
- No configuration management

## Recommended Improvements

### Priority 1: Critical Security Enhancements

```javascript
// 1. Install and configure security middleware
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult, param } = require('express-validator');

// Apply security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"]
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. Configure rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Stricter rate limit for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: 'Too many requests from this IP for this endpoint.'
});

app.use('/api/', limiter);

// 3. Request body size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 4. Global error handler
app.use((err, req, res, next) => {
  // Log error for debugging (don't expose to client)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method
  });

  // Don't leak error details in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message;

  res.status(statusCode).json({
    error: {
      message,
      statusCode,
      ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
    }
  });
});

// 5. 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: {
      message: 'Resource not found',
      statusCode: 404
    }
  });
});
```

### Priority 2: Input Validation and Sanitization

```javascript
// Validation middleware helper
const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: {
        message: 'Validation failed',
        details: errors.array()
      }
    });
  }
  next();
};

// Sanitization helper
const sanitizeInput = (value) => {
  if (typeof value === 'string') {
    return value.trim().replace(/[<>]/g, '');
  }
  return value;
};

// Updated /health endpoint with query validation
app.get('/health', [
  query('format').optional().isIn(['json', 'text'])
], validate, (req, res) => {
  const format = req.query.format || 'json';

  if (format === 'text') {
    res.set('Content-Type', 'text/plain');
    res.send(`OK - ${new Date().toISOString()}`);
  } else {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  }
});

// Updated /users endpoint with validation
app.get('/users', strictLimiter, [
  query('id').optional().isInt({ min: 1 }),
  query('limit').optional().isInt({ min: 1, max: 100 }),
  query('offset').optional().isInt({ min: 0 })
], validate, (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const { id, limit, offset } = req.query;

  let result = users;

  // Filter by ID if provided
  if (id) {
    result = result.find(u => u.id === parseInt(id));
    if (!result) {
      return res.status(404).json({
        error: {
          message: 'User not found',
          statusCode: 404
        }
      });
    }
  }

  // Apply pagination
  if (limit) {
    const start = offset ? parseInt(offset) : 0;
    result = result.slice(start, start + parseInt(limit));

    if (Array.isArray(users) && result.length === 0 && start < users.length) {
      return res.status(400).json({
        error: {
          message: 'Invalid pagination parameters',
          statusCode: 400
        }
      });
    }
  }

  res.json({
    data: result,
    meta: {
      count: Array.isArray(result) ? result.length : 1,
      timestamp: new Date().toISOString()
    }
  });
});
```

### Priority 3: Additional Security Measures

```javascript
// 6. CORS configuration
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
}));

// 7. Request logging
const morgan = require('morgan');
app.use(morgan('combined', {
  skip: (req, res) => req.path === '/health'
}));

// 8. Security-related response headers
app.use((req, res, next) => {
  res.removeHeader('X-Powered-By');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  next();
});

// 9. Timeout handling
const TIMEOUT = 30000; // 30 seconds
app.use((req, res, next) => {
  res.setTimeout(TIMEOUT, () => {
    console.error('Request timeout:', req.path);
    if (!res.headersSent) {
      res.status(408).json({
        error: {
          message: 'Request timeout',
          statusCode: 408
        }
      });
    }
  });
  next();
});

// 10. Handle uncaught exceptions and unhandled rejections
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  // Perform cleanup if needed
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
});
```

### Priority 4: Environment Configuration

```javascript
// Load environment variables
require('dotenv').config();

const config = {
  port: process.env.PORT || 3000,
  env: process.env.NODE_ENV || 'development',
  allowedOrigins: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  rateLimitWindow: parseInt(process.env.RATE_LIMIT_WINDOW) || 900000,
  rateLimitMax: parseInt(process.env.RATE_LIMIT_MAX) || 100
};

// Graceful shutdown
const server = app.listen(config.port, () => {
  console.log(`Server running on port ${config.port} in ${config.env} mode`);
});

const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));
