/**
 * Secure Express.js Application
 * Improved version with comprehensive error handling, input validation, and security best practices
 */

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ============================================================================
// CONFIGURATION
// ============================================================================
const config = {
  port: process.env.PORT || 3000,
  env: process.env.NODE_ENV || 'development',
  allowedOrigins: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  rateLimitWindow: parseInt(process.env.RATE_LIMIT_WINDOW) || 900000, // 15 minutes
  rateLimitMax: parseInt(process.env.RATE_LIMIT_MAX) || 100,
  requestTimeout: 30000, // 30 seconds
  maxBodySize: '10kb'
};

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Apply Helmet for security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", 'data:', 'https:'],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"]
    }
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  },
  noSniff: true,
  frameguard: { action: 'deny' },
  xssFilter: true,
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' }
}));

// CORS configuration
app.use(cors({
  origin: (origin, callback) => {
    // Allow requests with no origin (like mobile apps or curl requests)
    if (!origin) return callback(null, true);

    if (config.allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400, // 24 hours
  optionsSuccessStatus: 204
}));

// Request logging (skip health endpoint to reduce noise)
if (config.env !== 'test') {
  app.use(morgan('combined', {
    skip: (req, res) => req.path === '/health'
  }));
}

// Rate limiting
const limiter = rateLimit({
  windowMs: config.rateLimitWindow,
  max: config.rateLimitMax,
  message: {
    error: {
      message: 'Too many requests from this IP, please try again later.',
      statusCode: 429
    }
  },
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => req.path === '/health', // Skip rate limiting for health checks
  handler: (req, res) => {
    console.warn(`Rate limit exceeded for IP: ${req.ip}`);
    res.status(429).json({
      error: {
        message: 'Too many requests from this IP, please try again later.',
        statusCode: 429
      }
    });
  }
});

// Stricter rate limit for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: config.rateLimitWindow,
  max: 20,
  message: {
    error: {
      message: 'Rate limit exceeded for this endpoint.',
      statusCode: 429
    }
  }
});

app.use('/api/', limiter);

// Body parsing with size limits
app.use(express.json({
  limit: config.maxBodySize,
  strict: true
}));

app.use(express.urlencoded({
  extended: true,
  limit: config.maxBodySize
}));

// Custom security headers (additional to Helmet)
app.use((req, res, next) => {
  // Remove Express signature
  res.removeHeader('X-Powered-By');

  // Additional security headers
  res.setHeader('X-Request-ID', require('crypto').randomBytes(16).toString('hex'));

  next();
});

// Timeout handler
app.use((req, res, next) => {
  res.setTimeout(config.requestTimeout, () => {
    if (!res.headersSent) {
      res.status(408).json({
        error: {
          message: 'Request timeout',
          statusCode: 408
        }
      });
    }
  });
  next();
});

// ============================================================================
// VALIDATION HELPERS
// ============================================================================

/**
 * Validation middleware to check for validation errors
 */
const validate = (req, res, next) => {
  const errors = validationResult(req);

  if (!errors.isEmpty()) {
    console.warn(`Validation failed for ${req.method} ${req.path}:`, errors.array());

    return res.status(400).json({
      error: {
        message: 'Validation failed',
        statusCode: 400,
        details: config.env === 'development' ? errors.array() : undefined
      }
    });
  }

  next();
};

/**
 * Sanitize input strings
 */
const sanitizeInput = (value) => {
  if (typeof value === 'string') {
    return value
      .trim()
      .replace(/[<>]/g, '') // Remove potential HTML tags
      .replace(/[\x00-\x1F\x7F]/g, ''); // Remove control characters
  }
  return value;
};

/**
 * Safe JSON response helper
 */
const safeJson = (res, data, statusCode = 200) => {
  try {
    res.status(statusCode).json(data);
  } catch (error) {
    console.error('JSON serialization error:', error);
    res.status(500).json({
      error: {
        message: 'Internal server error',
        statusCode: 500
      }
    });
  }
};

// ============================================================================
// ERROR HANDLING
// ============================================================================

/**
 * Global error handler
 */
app.use((err, req, res, next) => {
  // Log error with context
  console.error('Error:', {
    message: err.message,
    statusCode: err.statusCode,
    path: req.path,
    method: req.method,
    ip: req.ip,
    userAgent: req.get('user-agent'),
    timestamp: new Date().toISOString(),
    ...(config.env === 'development' && { stack: err.stack })
  });

  // Determine status code
  const statusCode = err.statusCode || 500;

  // Don't leak error details in production
  const message = config.env === 'production' && statusCode === 500
    ? 'Internal Server Error'
    : err.message;

  // Send error response
  if (!res.headersSent) {
    safeJson(res, {
      error: {
        message,
        statusCode,
        ...(config.env === 'development' && { stack: err.stack })
      }
    }, statusCode);
  }
});

/**
 * CORS error handler
 */
app.use((err, req, res, next) => {
  if (err.message === 'Not allowed by CORS') {
    return res.status(403).json({
      error: {
        message: 'Cross-origin request not allowed',
        statusCode: 403
      }
    });
  }
  next(err);
});

/**
 * JSON parsing error handler
 */
app.use((err, req, res, next) => {
  if (err instanceof SyntaxError && err.status === 400 && 'body' in err) {
    return res.status(400).json({
      error: {
        message: 'Invalid JSON in request body',
        statusCode: 400
      }
    });
  }
  next(err);
});

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint
 * GET /health
 */
app.get('/health', [
  query('format').optional().isIn(['json', 'text']).withMessage('Format must be json or text')
], validate, (req, res) => {
  try {
    const format = sanitizeInput(req.query.format) || 'json';

    if (format === 'text') {
      res.set('Content-Type', 'text/plain');
      res.send(`OK - ${new Date().toISOString()}`);
    } else {
      safeJson(res, {
        status: 'ok',
        timestamp: new Date().toISOString(),
        environment: config.env
      });
    }
  } catch (error) {
    next(error);
  }
});

/**
 * Get users endpoint
 * GET /users
 */
app.get('/users', strictLimiter, [
  query('id').optional().isInt({ min: 1 }).withMessage('ID must be a positive integer'),
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  query('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a non-negative integer'),
  query('sort').optional().isIn(['id', 'name', 'email']).withMessage('Invalid sort field'),
  query('order').optional().isIn(['asc', 'desc']).withMessage('Order must be asc or desc')
], validate, (req, res) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    ];

    // Parse and validate query parameters
    const id = req.query.id ? parseInt(req.query.id) : null;
    const limit = req.query.limit ? parseInt(req.query.limit) : users.length;
    const offset = req.query.offset ? parseInt(req.query.offset) : 0;
    const sort = req.query.sort || 'id';
    const order = req.query.order || 'asc';

    let result = [...users];

    // Filter by ID if provided
    if (id) {
      result = result.find(u => u.id === id);

      if (!result) {
        return res.status(404).json({
          error: {
            message: 'User not found',
            statusCode: 404
          }
        });
      }
    } else {
      // Apply sorting
      result.sort((a, b) => {
        const aVal = a[sort];
        const bVal = b[sort];

        if (aVal < bVal) return order === 'asc' ? -1 : 1;
        if (aVal > bVal) return order === 'asc' ? 1 : -1;
        return 0;
      });

      // Validate pagination
      if (offset >= result.length) {
        return res.status(400).json({
          error: {
            message: 'Offset exceeds total number of records',
            statusCode: 400
          }
        });
      }

      // Apply pagination
      result = result.slice(offset, offset + limit);
    }

    safeJson(res, {
      data: result,
      meta: {
        count: Array.isArray(result) ? result.length : 1,
        total: users.length,
        timestamp: new Date().toISOString()
      }
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Create user endpoint (example for POST validation)
 * POST /users
 */
app.post('/users', strictLimiter, [
  body('name')
    .trim()
    .notEmpty().withMessage('Name is required')
    .isLength({ min: 1, max: 100 }).withMessage('Name must be between 1 and 100 characters')
    .matches(/^[a-zA-Z\s'-]+$/).withMessage('Name contains invalid characters'),
  body('email')
    .trim()
    .notEmpty().withMessage('Email is required')
    .isEmail().withMessage('Invalid email format')
    .normalizeEmail()
    .isLength({ max: 255 }).withMessage('Email is too long')
], validate, (req, res) => {
  try {
    const { name, email } = req.body;

    // Sanitize inputs
    const sanitizedName = sanitizeInput(name);
    const sanitizedEmail = sanitizeInput(email).toLowerCase();

    // In a real application, you would save to a database here

    safeJson(res, {
      data: {
        id: Math.floor(Math.random() * 1000) + 4, // Mock ID
        name: sanitizedName,
        email: sanitizedEmail
      },
      message: 'User created successfully'
    }, 201);
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// 404 HANDLER
// ============================================================================

/**
 * Handle 404 - Route not found
 */
app.use((req, res) => {
  console.warn(`404 - Route not found: ${req.method} ${req.path}`);

  res.status(404).json({
    error: {
      message: 'Resource not found',
      statusCode: 404,
      path: req.path,
      method: req.method
    }
  });
});

// ============================================================================
// SERVER STARTUP & GRACEFUL SHUTDOWN
// ============================================================================

const server = app.listen(config.port, () => {
  console.log(`Server running on port ${config.port} in ${config.env} mode`);
  console.log(`Allowed origins: ${config.allowedOrigins.join(', ')}`);
});

/**
 * Graceful shutdown handler
 */
const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  // Stop accepting new connections
  server.close(() => {
    console.log('Server closed successfully');
    process.exit(0);
  });

  // Force shutdown after timeout
  const shutdownTimeout = setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);

  // Clear timeout if shutdown completes
  shutdownTimeout.unref();
};

// Handle shutdown signals
process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

/**
 * Handle uncaught exceptions
 */
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', {
    message: err.message,
    stack: err.stack,
    timestamp: new Date().toISOString()
  });

  // Perform cleanup if needed
  gracefulShutdown('uncaughtException');
});

/**
 * Handle unhandled promise rejections
 */
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection:', {
    reason,
    promise,
    timestamp: new Date().toISOString()
  });
});

module.exports = app;

