const express = require('express');
const helmet = require('helmet'); // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting
const expressSanitizer = require('express-sanitizer'); // Input sanitization
const { body, query, validationResult } = require('express-validator'); // Input validation

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Set security headers using Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:"]
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  noSniff: true,
  frameguard: { action: 'deny' },
  xssFilter: true
}));

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later',
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all routes
app.use(limiter);

// Stricter rate limiting for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: 'Too many requests to this endpoint, please try again later'
});

// Request body size limiting
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input sanitization
app.use(expressSanitizer());

// ============================================
// VALIDATION MIDDLEWARE
// ============================================

// Validation error handler
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array()
    });
  }
  next();
};

// ============================================
// LOGGING MIDDLEWARE
// ============================================

app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

// 404 handler - must be after all routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource was not found',
    path: req.path
  });
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error for debugging
  console.error('Error:', err);

  // Don't leak error details in production
  const isDevelopment = process.env.NODE_ENV !== 'production';

  const statusCode = err.statusCode || 500;
  const response = {
    error: err.name || 'Internal Server Error',
    message: isDevelopment ? err.message : 'An unexpected error occurred'
  };

  if (isDevelopment && err.stack) {
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
});

// ============================================
// ROUTES
// ============================================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    next(error); // Pass to global error handler
  }
});

// Users endpoint with validation and security
app.get('/users', [
  // Validate query parameters
  query('id').optional().isInt({ min: 1 }).toInt(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('email').optional().isEmail().normalizeEmail(),
  handleValidationErrors
], (req, res) => {
  try {
    const { id, limit, email } = req.query;

    // Mock user data - in production, fetch from database
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' }
    ];

    let filteredUsers = allUsers;

    // Filter by ID if provided
    if (id) {
      filteredUsers = filteredUsers.filter(user => user.id === id);
    }

    // Filter by email if provided
    if (email) {
      filteredUsers = filteredUsers.filter(user => user.email === email);
    }

    // Apply limit if provided
    if (limit) {
      filteredUsers = filteredUsers.slice(0, limit);
    }

    // Sanitize output to prevent XSS
    const sanitizedUsers = filteredUsers.map(user => ({
      id: user.id,
      name: req.sanitize(user.name),
      email: req.sanitize(user.email)
    }));

    res.json({
      data: sanitizedUsers,
      count: sanitizedUsers.length,
      timestamp: new Date().toISOString()
    });

  } catch (error) {
    next(error); // Pass to global error handler
  }
});

// Secure user search endpoint with input validation
app.get('/users/search', [
  query('q').trim().isLength({ min: 1, max: 50 }).escape(),
  query('page').optional().isInt({ min: 1 }).toInt(),
  handleValidationErrors
], (req, res) => {
  try {
    const { q, page = 1 } = req.query;

    // Validate search query further
    if (/[^a-zA-Z0-9\s\-@.]/.test(q)) {
      return res.status(400).json({
        error: 'Invalid search query',
        message: 'Search query contains invalid characters'
      });
    }

    // In production, implement actual database search with parameterized queries
    res.json({
      message: 'Search endpoint (mock)',
      query: q,
      page,
      timestamp: new Date().toISOString()
    });

  } catch (error) {
    next(error);
  }
});

// ============================================
// SERVER STARTUP
// ============================================

if (require.main === module) {
  const PORT = process.env.PORT || 3000;

  const server = app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });

  // Graceful shutdown handling
  const gracefulShutdown = (signal) => {
    console.log(`\n${signal} received. Starting graceful shutdown...`);
    server.close(() => {
      console.log('Server closed. Exiting process.');
      process.exit(0);
    });

    // Force close after 10 seconds
    setTimeout(() => {
      console.error('Forcing shutdown after timeout...');
      process.exit(1);
    }, 10000);
  };

  process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
  process.on('SIGINT', () => gracefulShutdown('SIGINT'));

  // Handle uncaught exceptions
  process.on('uncaughtException', (err) => {
    console.error('Uncaught Exception:', err);
    gracefulShutdown('uncaughtException');
  });

  // Handle unhandled promise rejections
  process.on('unhandledRejection', (reason, promise) => {
    console.error('Unhandled Rejection at:', promise, 'reason:', reason);
    gracefulShutdown('unhandledRejection');
  });
}

module.exports = app;

