# Security Review: app.js - Error Handling & Input Validation

## Current Issues Identified

### 1. **Missing Input Validation**
- No validation on query parameters or request body
- No rate limiting (vulnerable to DoS attacks)
- No request size limits (vulnerable to request flooding)

### 2. **Inadequate Error Handling**
- No try-catch blocks for middleware
- No custom error handlers
- No logging of errors for security monitoring
- Sensitive stack traces may leak to users

### 3. **Missing Security Headers**
- No Helmet.js for security headers
- No CORS configuration
- Missing Content-Security-Policy
- No protection against clickjacking

### 4. **Other Security Concerns**
- No HTTPS enforcement (in production)
- No request ID tracking for audit trails
- No input sanitization
- Database queries vulnerable to injection (if database added)
- Sensitive data in responses (no filtering)

---

## Recommended Improvements

### Priority 1: Critical Security Fixes

#### 1.1 Add Body Parser with Size Limits
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
```

#### 1.2 Add Rate Limiting
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP'
});
app.use(limiter);
```

#### 1.3 Add Security Headers (Helmet.js)
```javascript
const helmet = require('helmet');
app.use(helmet());
```

#### 1.4 Input Validation Schema
```javascript
const Joi = require('joi');

const userQuerySchema = Joi.object({
  id: Joi.number().integer().min(1).max(1000).optional(),
  email: Joi.string().email().optional(),
  limit: Joi.number().integer().min(1).max(100).default(10)
});
```

### Priority 2: Error Handling Improvements

#### 2.1 Centralized Error Handler
```javascript
class AppError extends Error {
  constructor(statusCode, message, isOperational = true) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = isOperational;
    Error.captureStackTrace(this, this.constructor);
  }
}

// Global error handler
app.use((err, req, res, next) => {
  // Log error for monitoring
  console.error(`[${new Date().toISOString()}] Error:`, {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    url: req.url,
    method: req.method,
    ip: req.ip
  });

  // Don't leak stack traces in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'development' 
    ? err.message 
    : 'An error occurred';

  res.status(statusCode).json({
    error: {
      message,
      ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
    },
    requestId: req.id
  });
});
```

#### 2.2 Async Error Wrapper
```javascript
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// Usage:
app.get('/users/:id', asyncHandler(async (req, res) => {
  const user = await getUser(req.params.id);
  if (!user) throw new AppError(404, 'User not found');
  res.json(user);
}));
```

### Priority 3: Request Validation Middleware

#### 3.1 Validation Middleware
```javascript
const validateQuery = (schema) => {
  return (req, res, next) => {
    const { error, value } = schema.validate(req.query, {
      abortEarly: false,
      stripUnknown: true
    });

    if (error) {
      const errors = error.details.map(detail => ({
        field: detail.path.join('.'),
        message: detail.message
      }));
      throw new AppError(400, 'Validation failed', errors);
    }

    req.query = value; // Use sanitized values
    next();
  };
};
```

#### 3.2 Sanitization Middleware
```javascript
const sanitizeInput = require('express-mongo-sanitize');
const xss = require('xss-clean');

app.use(sanitizeInput()); // NoSQL injection protection
app.use(xss()); // XSS protection
```

### Priority 4: Security Hardening

#### 4.1 CORS Configuration
```javascript
const cors = require('cors');

app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));
```

#### 4.2 Request ID for Auditing
```javascript
const { v4: uuidv4 } = require('uuid');
app.use((req, res, next) => {
  req.id = req.headers['x-request-id'] || uuidv4();
  res.setHeader('X-Request-ID', req.id);
  next();
});
```

#### 4.3 HTTP Strict Transport Security
```javascript
app.use(helmet.hsts({
  maxAge: 31536000,
  includeSubDomains: true,
  preload: true
}));
```

#### 4.4 Content Security Policy
```javascript
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", "data:"],
    connectSrc: ["'self'"]
  }
}));
```

---

## Complete Secure Implementation Example

### Secure app.js
```javascript
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const Joi = require('joi');
const { v4: uuidv4 } = require('uuid');

const app = express();

// Security headers
app.use(helmet());
app.use(helmet.hsts({
  maxAge: 31536000,
  includeSubDomains: true,
  preload: true
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false
});
app.use('/api', limiter);

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Request ID for auditing
app.use((req, res, next) => {
  req.id = req.headers['x-request-id'] || uuidv4();
  res.setHeader('X-Request-ID', req.id);
  next();
});

// Custom error class
class AppError extends Error {
  constructor(statusCode, message, details = null) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true;
    this.details = details;
    Error.captureStackTrace(this, this.constructor);
  }
}

// Validation schemas
const userParamsSchema = Joi.object({
  id: Joi.number().integer().positive().required()
});

const userQuerySchema = Joi.object({
  fields: Joi.string().pattern(/^[a-zA-Z0-9,_-]+$/).optional(),
  limit: Joi.number().integer().min(1).max(100).default(10)
});

// Validation middleware
const validate = (schema, property = 'params') => {
  return (req, res, next) => {
    const { error, value } = schema.validate(req[property], {
      abortEarly: false,
      stripUnknown: true
    });

    if (error) {
      const details = error.details.map(detail => ({
        field: detail.path.join('.'),
        message: detail.message
      }));
      throw new AppError(400, 'Validation failed', details);
    }

    req[property] = value;
    next();
  };
};

// Routes with error handling and validation
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users',
  validate(userQuerySchema, 'query'),
  (req, res) => {
    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' }
      ];

      // Apply field filtering if requested
      if (req.query.fields) {
        const fields = req.query.fields.split(',');
        const filteredUsers = users.map(user => {
          const filtered = {};
          fields.forEach(field => {
            if (user[field] !== undefined) {
              filtered[field] = user[field];
            }
          });
          return filtered;
        });
        return res.json(filteredUsers.slice(0, req.query.limit));
      }

      res.json(users.slice(0, req.query.limit));
    } catch (error) {
      throw new AppError(500, 'Failed to retrieve users');
    }
  }
);

app.get('/users/:id',
  validate(userParamsSchema, 'params'),
  (req, res) => {
    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' }
      ];

      const user = users.find(u => u.id === req.params.id);

      if (!user) {
        throw new AppError(404, 'User not found');
      }

      res.json(user);
    } catch (error) {
      if (error instanceof AppError) throw error;
      throw new AppError(500, 'Failed to retrieve user');
    }
  }
);

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: {
      message: 'Resource not found',
      requestId: req.id
    }
  });
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error for security monitoring
  console.error(`[${new Date().toISOString()}] Error:`, {
    requestId: req.id,
    message: err.message,
    statusCode: err.statusCode || 500,
    url: req.url,
    method: req.method,
    ip: req.ip,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });

  const statusCode = err.statusCode || 500;
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(statusCode).json({
    error: {
      message: isDevelopment ? err.message : 'An internal error occurred',
      requestId: req.id,
      ...(err.details && isDevelopment && { details: err.details })
    }
  });
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = app;
```

---

## Additional Security Recommendations

### 1. Environment Variables
```bash
# .env file (never commit to git)
NODE_ENV=production
PORT=3000
ALLOWED_ORIGINS=https://yourdomain.com
RATE_LIMIT_WINDOW=900000
RATE_LIMIT_MAX=100
```

### 2. Package Dependencies
```bash
# Run regularly to check for vulnerabilities
npm audit
npm audit fix
```

### 3. Add to package.json
```json
{
  "dependencies": {
    "express": "^4.18.2",
    "helmet": "^7.1.0",
    "express-rate-limit": "^7.1.5",
    "joi": "^17.11.0",
    "uuid": "^9.0.1",
    "cors": "^2.8.5",
    "xss-clean": "^0.1.4",
    "express-mongo-sanitize": "^2.2.0"
  }
}
```

### 4. Testing Security
- Use OWASP ZAP for security scanning
- Implement unit tests for validation
- Add integration tests for error scenarios
- Regular penetration testing

### 5. Monitoring & Logging
- Implement structured logging (winston/pino)
- Set up alerts for rate limit breaches
- Log failed validation attempts
- Monitor for suspicious patterns

---

## Summary Checklist

- [ ] Add Helmet.js for security headers
- [ ] Implement rate limiting
- [ ] Add request/response size limits
- [ ] Implement input validation with Joi
- [ ] Add centralized error handling
- [ ] Implement request ID tracking
- [ ] Add sanitization middleware
- [ ] Configure CORS properly
- [ ] Implement 404 handler
- [ ] Add structured logging
- [ ] Set up environment configuration
- [ ] Add security monitoring
- [ ] Regular dependency audits
- [ ] Implement CSP headers
- [ ] Add HTTPS/HSTS enforcement
- [ ] Create security test suite

