const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Set various HTTP headers for security
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));

// Parse JSON with size limit to prevent DoS attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting to prevent brute force and DDoS attacks
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true,
  legacyHeaders: false,
  trustProxy: true,
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Stricter limit for sensitive endpoints
  message: {
    error: 'Too many attempts, please try again later.'
  },
});

app.use('/api/', apiLimiter);

// ============================================================================
// VALIDATION MIDDLEWARE
// ============================================================================

const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path || err.param,
        message: err.msg,
        value: err.value
      }))
    });
  }
  next();
};

const sanitizeResponse = (data, fieldsToRemove = []) => {
  if (Array.isArray(data)) {
    return data.map(item => sanitizeResponse(item, fieldsToRemove));
  }
  if (typeof data === 'object' && data !== null) {
    const sanitized = { ...data };
    fieldsToRemove.forEach(field => delete sanitized[field]);
    return sanitized;
  }
  return data;
};

// ============================================================================
// CUSTOM ERROR CLASSES
// ============================================================================

class AppError extends Error {
  constructor(message, statusCode = 500, isOperational = true) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = isOperational;
    this.timestamp = new Date().toISOString();
    Error.captureStackTrace(this, this.constructor);
  }
}

class ValidationError extends AppError {
  constructor(message = 'Validation failed') {
    super(message, 400);
  }
}

class NotFoundError extends AppError {
  constructor(message = 'Resource not found') {
    super(message, 404);
  }
}

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

// Async handler wrapper to catch errors in async routes
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// Global error handler (must be last)
app.use((err, req, res, next) => {
  // Log error securely
  console.error('Error:', JSON.stringify({
    message: err.message,
    statusCode: err.statusCode,
    url: req.url,
    method: req.method,
    ip: req.ip,
    userAgent: req.get('user-agent'),
    timestamp: new Date().toISOString(),
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  }));

  // Handle operational vs programming errors
  const statusCode = err.statusCode || 500;
  const message = (process.env.NODE_ENV === 'production' && !err.isOperational)
    ? 'An internal server error occurred'
    : err.message;

  res.status(statusCode).json({
    error: message,
    ...(process.env.NODE_ENV === 'development' && {
      stack: err.stack,
      details: err.details
    })
  });
});

// 404 handler for undefined routes
app.use((req, res, next) => {
  next(new NotFoundError(`Route ${req.method} ${req.url} not found`));
});

// ============================================================================
// ROUTES
// ============================================================================

// Health check endpoint
app.get('/health', asyncHandler(async (req, res) => {
    // In a real application, you'd check:
    // - Database connectivity
    // - External service availability
    // - File system access
    // - Memory usage

    const healthStatus = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: process.env.NODE_ENV || 'development',
      version: process.env.APP_VERSION || '1.0.0'
    };

    res.json(healthStatus);
}));

// Users endpoint with validation and security
app.get('/users',
  [
    // Validate and sanitize query parameters
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be an integer between 1 and 100')
      .toInt(),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer')
      .toInt(),
    query('sort')
      .optional()
      .isIn(['id', 'name', 'email'])
      .withMessage('Sort must be one of: id, name, email')
      .trim(),
    query('fields')
      .optional()
      .customSanitizer(value => {
        if (typeof value === 'string') {
          return value.split(',').map(f => f.trim()).filter(f => f.length > 0);
        }
        return value;
      })
      .custom(fields => {
        if (Array.isArray(fields)) {
          const allowedFields = ['id', 'name', 'email'];
          const invalidFields = fields.filter(f => !allowedFields.includes(f));
          if (invalidFields.length > 0) {
            throw new Error(`Invalid fields: ${invalidFields.join(', ')}`);
          }
        }
        return true;
      }),
    handleValidationErrors
  ],
  asyncHandler(async (req, res) => {
    const { limit = 10, offset = 0, sort = 'id', fields } = req.query;

    // In a real app, this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    ];

    // Validate that users array exists and is not empty
    if (!Array.isArray(users)) {
      throw new AppError('Invalid users data', 500);
    }

    // Apply sorting with proper validation of sort field
    const allowedSortFields = ['id', 'name', 'email'];
    const sortField = allowedSortFields.includes(sort) ? sort : 'id';

    const sortedUsers = [...users].sort((a, b) => {
      if (a[sortField] < b[sortField]) return -1;
      if (a[sortField] > b[sortField]) return 1;
      return 0;
    });

    // Apply pagination
    const paginatedUsers = sortedUsers.slice(offset, offset + limit);

    // Filter fields if requested (projection)
    let responseUsers = paginatedUsers;
    if (fields && Array.isArray(fields) && fields.length > 0) {
      responseUsers = paginatedUsers.map(user => {
        const filtered = {};
        fields.forEach(field => {
          if (user.hasOwnProperty(field)) {
            filtered[field] = user[field];
          }
        });
        return filtered;
      });
    }

    // Return response with metadata
    res.json({
      data: responseUsers,
      meta: {
        total: users.length,
        count: responseUsers.length,
        limit: limit,
        offset: offset,
        sort: sortField
      }
    });
  })
);

// Example of a POST endpoint with input validation
app.post('/users',
  [
    body('name')
      .trim()
      .notEmpty()
      .withMessage('Name is required')
      .isLength({ min: 2, max: 100 })
      .withMessage('Name must be between 2 and 100 characters')
      .escape(), // Escape HTML entities to prevent XSS
    body('email')
      .trim()
      .notEmpty()
      .withMessage('Email is required')
      .isEmail()
      .withMessage('Invalid email format')
      .normalizeEmail(), // Normalize email address
    handleValidationErrors
  ],
  asyncHandler(async (req, res) => {
    const { name, email } = req.body;

    // In a real app, you would:
    // 1. Check for duplicate email
    // 2. Hash passwords if applicable
    // 3. Save to database
    // 4. Return the created resource with 201 status

    // Simulate user creation
    const newUser = {
      id: Date.now(), // In production, use proper UUID generation
      name,
      email,
      createdAt: new Date().toISOString()
    };

    res.status(201).json({
      data: newUser,
      message: 'User created successfully'
    });
  })
);

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Graceful shutdown
const shutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force close after 10 seconds
  setTimeout(() => {
    console.error('Forcing server shutdown...');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  shutdown('UNCAUGHT_EXCEPTION');
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  shutdown('UNHANDLED_REJECTION');
});

module.exports = { app, server };

