// Improved application with security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Security headers - protects against well-known web vulnerabilities
app.use(helmet());

// 2. Rate limiting - prevents DoS and brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later',
    retryAfter: 900
  },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api', limiter);

// 3. Request body parsing with size limits
app.use(express.json({ 
  limit: '10kb', // Prevent DoS via large payloads
  strict: true // Only accept arrays and objects
}));

// 4. CORS configuration (adjust origins as needed)
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', process.env.ALLOWED_ORIGINS || 'http://localhost:3000');
  res.header('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  // res.header('Access-Control-Allow-Credentials', 'true');
  next();
});

// ============================================================================
// VALIDATION HELPER FUNCTIONS
// ============================================================================

// Middleware to check validation results
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Log validation failures for security monitoring
    console.warn(`Validation failed for ${req.method} ${req.path}:`, {
      ip: req.ip,
      errors: errors.array(),
      timestamp: new Date().toISOString()
    });

    return res.status(400).json({
      error: 'Invalid request data',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg
      }))
    });
  }
  next();
};

// Sanitization for query parameters
const sanitizeQueryParams = (req, res, next) => {
  // Remove unexpected query parameters
  const allowedParams = ['page', 'limit', 'sort', 'filter'];
  const providedParams = Object.keys(req.query);

  const unexpectedParams = providedParams.filter(p => !allowedParams.includes(p));
  if (unexpectedParams.length > 0) {
    console.warn(`Unexpected query params blocked: ${unexpectedParams.join(', ')}`);
  }

  // Sanitize numeric/boolean parameters
  ['page', 'limit'].forEach(param => {
    if (req.query[param]) {
      const num = parseInt(req.query[param], 10);
      req.query[param] = isNaN(num) ? null : Math.max(1, Math.min(num, 1000));
    }
  });

  next();
};

// ============================================================================
// LOGGING MIDDLEWARE
// ============================================================================

app.use((req, res, next) => {
  const startTime = Date.now();

  // Log request (be careful not to log sensitive data)
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`, {
    ip: req.ip,
    userAgent: req.get('user-agent')
  });

  // Override res.json to log responses
  const originalJson = res.json.bind(res);
  res.json = function(data) {
    const duration = Date.now() - startTime;
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`, {
      statusCode: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip
    });
    return originalJson(data);
  };

  next();
});

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

// Centralized error handler
app.use((err, req, res, next) => {
  // Log the full error for debugging
  console.error(`[${new Date().toISOString()}] Error:`, {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Determine status code
  const statusCode = err.statusCode || err.status || 500;

  // Send appropriate error response (don't expose internal details in production)
  res.status(statusCode).json({
    error: process.env.NODE_ENV === 'development' 
      ? err.message 
      : 'An internal server error occurred',
    requestId: req.headers['x-request-id'] || 'unknown',
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// Handle 404 errors
app.use((req, res) => {
  console.warn(`[${new Date().toISOString()}] 404 Not Found: ${req.method} ${req.path}`, {
    ip: req.ip
  });

  res.status(404).json({
    error: 'Resource not found',
    path: req.path
  });
});

// ============================================================================
// ROUTES
// ============================================================================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    next(error);
  }
});

// Users endpoint with pagination and validation
app.get('/users',
  sanitizeQueryParams,

  // Validate query parameters
  [
    query('page')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Page must be between 1 and 100'),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
    query('sort')
      .optional()
      .matches(/^(id|name|email):(asc|desc)$/)
      .withMessage('Sort must be in format: field:direction (e.g., name:asc)'),
    query('filter')
      .optional()
      .trim()
      .escape()
      .isLength({ max: 100 })
      .withMessage('Filter must be 100 characters or less')
  ],

  handleValidationErrors,

  (req, res, next) => {
    try {
      const page = parseInt(req.query.page) || 1;
      const limit = parseInt(req.query.limit) || 10;
      const sort = req.query.sort || 'id:asc';

      // In production, fetch from database with proper pagination
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Sanitize response data - remove sensitive fields if needed
      const sanitizedUsers = users.map(user => ({
        ...user,
        email: user.email.replace(/(?<=.{2}).(?=.*@)/g, '*') // Mask emails for security
      }));

      res.json({
        data: sanitizedUsers,
        pagination: {
          page,
          limit,
          total: users.length,
          totalPages: Math.ceil(users.length / limit)
        },
        sort
      });
    } catch (error) {
      next(error);
    }
  }
);

// ============================================================================
// SERVER STARTUP
// ============================================================================

// Only start server if not being imported (e.g., during testing)
if (require.main === module) {
  const PORT = process.env.PORT || 3000;

  // Validate port
  const numericPort = parseInt(PORT, 10);
  if (isNaN(numericPort) || numericPort < 1 || numericPort > 65535) {
    console.error('Invalid PORT configuration');
    process.exit(1);
  }

  const server = app.listen(numericPort, () => {
    console.log(`Server running on port ${numericPort}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });

  // Graceful shutdown handling
  const gracefulShutdown = (signal) => {
    console.log(`\n${signal} received. Starting graceful shutdown...`);
    server.close(() => {
      console.log('Server closed successfully');
      process.exit(0);
    });

    // Force shutdown after 10 seconds
    setTimeout(() => {
      console.error('Forcing shutdown after timeout');
      process.exit(1);
    }, 10000);
  };

  process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
  process.on('SIGINT', () => gracefulShutdown('SIGINT'));
}

module.exports = app;

